data_contract.frontend_api:
// ApiErrorResponse (api/types.ts) guadagna:
//   authorization?: { reason: 'missing_permission' | 'denied'; permission: string | null }
export function forbiddenMessage(error: unknown, i18n: I18nInstance): string | null
//   non-axios / status != 403          -> null
//   reason missing_permission           -> t('common.missingPermission', { ability: abilityLabel(p), module: resourceLabel(resource(p)) })
//                                          it: "Non hai il permesso «{{ability}}» sul modulo «{{module}}»."
//   reason denied / blocco assente      -> response.data.message se non vuoto
//   altrimenti                          -> t('common.forbidden')
export function apiErrorMessage(error: unknown, fallback: string, i18n: I18nInstance): string
//   forbiddenMessage(error, i18n) ?? fallback
